args.new:
test("AC-3 Mismatched new password and repeat is refused", async ({ page }, testInfo) => {
  const changePasswordPage = new ChangePasswordPage(page);

  await test.step("Given I navigate to \"/#/login\"", async () => {
    await page.goto("/#/login");
  });

  await test.step("Dismiss cookie consent if present", async () => {
    const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
    await dismissBtn.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
    if (await dismissBtn.isVisible()) { await dismissBtn.click(); }
  });

  await test.step("When I find the Email field and enter the test user email", async () => {
    await page.getByLabel('Email').fill(process.env["AQA_APP_USER"] ?? "");
  });

  await test.step("And I find the Password field and enter the test user password", async () => {
    await page.locator("input[type='password']").fill(process.env["AQA_APP_PASS"] ?? "");
  });

  await test.step("And I click Log in", async () => {
    await page.getByRole('button', { name: 'Login' }).click();
  });

  await test.step("Precondition: login succeeded", async () => {
    await expect(page.getByRole("button", { name: "Show/hide account menu" })).toBeVisible({ timeout: 10000 });
  });

  await test.step("And I navigate to \"/#/privacy-security/change-password\"", async () => {
    await changePasswordPage.goto();
  });

  await test.step("Precondition: change-password form is visible", async () => {
    await expect(changePasswordPage.fieldToEnterTheCurrentPasswordInput).toBeVisible({ timeout: 5000 });
  });

  await test.step("And I find the \"Current Password\" field and enter the test user password", async () => {
    await changePasswordPage.fieldToEnterTheCurrentPasswordInput.fill(process.env["AQA_APP_PASS"] ?? "");
  });

  await test.step("And I find the \"New Password\" field and enter \"NewP@ssw0rd1!\"", async () => {
    await changePasswordPage.fieldForTheNewPasswordInput.fill("NewP@ssw0rd1!");
  });

  await test.step("And I find the \"Repeat New Password\" field and enter \"DifferentP@ss999!\"", async () => {
    await changePasswordPage.fieldToRepeatTheNewPasswordInput.fill("DifferentP@ss999!");
  });

  await test.step("Then the Change button is disabled", async () => {
    await expect(changePasswordPage.buttonToConfirmTheChangeButton).toBeDisabled();
  });
});

